"""Preservation primitives over generated bytes, trees and interruptions.

Existing originals are never replaced, an interrupted write leaves the previous bytes and no
debris, an inventory reads without touching what it reads, and a package is a deterministic
function of its payload that verification can tell from any other.
"""

import os
from pathlib import Path
import stat
import tempfile
import unittest
from unittest import mock

from hypothesis import given
from hypothesis import strategies as st

from berman import files
from berman.archive import package
from berman.files import Decision
from tests.support.properties import budget

contents = st.binary(max_size=64)
names = st.text(alphabet='abcdefg', min_size=1, max_size=6)
# Relative paths with one to three components; a name is a file in one tree and a folder in none.
trees = st.dictionaries(
    st.lists(names, min_size=1, max_size=3).map(
        lambda parts: '/'.join(f'{p}.d' for p in parts[:-1]) + ('/' if parts[1:] else '') + parts[-1]
    ),
    contents,
    min_size=1,
    max_size=6,
)


def state(path):
    status = path.lstat()
    return path.read_bytes(), status.st_mtime_ns, status.st_ino


def build(root, tree):
    for relative, data in tree.items():
        (root / relative).parent.mkdir(parents=True, exist_ok=True)
        (root / relative).write_bytes(data)


def metadata(root):
    """Every entry's mode and modification time, without following symlinks."""
    found = {}
    for parent, folders, leaves in os.walk(root):
        for name in folders + leaves:
            status = (Path(parent) / name).lstat()
            found[str((Path(parent) / name).relative_to(root))] = (stat.S_IMODE(status.st_mode), status.st_mtime_ns)
    return found


class KeepTests(unittest.TestCase):
    @budget(100)
    @given(contents, contents)
    def test_keep_never_replaces_an_existing_artifact(self, first, second):
        with tempfile.TemporaryDirectory() as temporary:
            path = Path(temporary).resolve() / 'evidence/kept.bin'
            files.keep(path, first)
            before = state(path)
            if second == first:
                files.keep(path, second)  # A retry of the same operation verifies its earlier copy.
            else:
                with self.assertRaisesRegex(Decision, 'Existing artifact differs; retained for inspection'):
                    files.keep(path, second)
            self.assertEqual(state(path), before)
            self.assertEqual([p.name for p in path.parent.iterdir()], ['kept.bin'])

    @budget(100)
    @given(st.none() | contents, contents, st.sampled_from(('os.replace', 'os.fsync')))
    def test_an_interrupted_write_leaves_the_previous_bytes_and_no_debris(self, old, new, step):
        with tempfile.TemporaryDirectory() as temporary:
            path = Path(temporary).resolve() / 'record.json'
            if old is not None:
                path.write_bytes(old)
            before = state(path) if old is not None else None
            with mock.patch(step, side_effect=OSError('interrupted')), self.assertRaisesRegex(OSError, 'interrupted'):
                files.atomic(path, new)
            self.assertEqual(state(path) if path.exists() else None, before)
            self.assertEqual([p.name for p in path.parent.iterdir()], ['record.json'] if old is not None else [])
            files.atomic(path, new)  # The same write, retried, completes.
            self.assertEqual(path.read_bytes(), new)
            self.assertEqual([p.name for p in path.parent.iterdir()], ['record.json'])


class InventoryTests(unittest.TestCase):
    @budget(60)
    @given(trees, st.data())
    def test_an_inventory_reads_without_touching_and_notices_every_change(self, tree, data):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary).resolve() / 'packet'
            root.mkdir()
            build(root, tree)
            untouched = metadata(root)
            recorded = files.inventory(root)
            self.assertEqual(files.inventory(root), recorded)
            self.assertEqual(metadata(root), untouched, 'taking an inventory changed the tree')
            self.assertEqual({row['path'] for row in recorded if row['type'] == 'file'}, set(tree))
            victim = root / data.draw(st.sampled_from(sorted(tree)))
            change = data.draw(st.sampled_from(('grow', 'remove', 'add', 'mode', 'symlink')))
            if change == 'grow':
                victim.write_bytes(victim.read_bytes() + b'+')
            elif change == 'remove':
                victim.unlink()
            elif change == 'add':
                (victim.parent / 'added-later.txt').write_bytes(b'later')
            elif change == 'mode':
                victim.chmod(stat.S_IMODE(victim.stat().st_mode) ^ 0o111)
            else:
                victim.unlink()
                victim.symlink_to('elsewhere')
            self.assertNotEqual(files.inventory(root), recorded, change)


class PackageTests(unittest.TestCase):
    @budget(60)
    @given(trees, st.sampled_from((0o644, 0o600, 0o755)), st.data())
    def test_a_package_is_deterministic_and_verification_tells_it_from_any_other(self, tree, mode, data):
        payload = {name: (content, stat.S_IFREG | mode) for name, content in tree.items()}
        payload['notes/'] = (b'', stat.S_IFDIR | 0o755)
        payload['notes/link'] = (os.fsencode('../elsewhere'), stat.S_IFLNK | 0o777)
        zipped = package.make_zip(payload, 'berman-analysis/')
        self.assertEqual(package.make_zip(dict(reversed(list(payload.items()))), 'berman-analysis/'), zipped)
        package.verify_zip(zipped, payload, 'berman-analysis/')
        victim = data.draw(st.sampled_from(sorted(tree)))
        content, kind = payload[victim]
        for name, changed in (
            ('bytes', dict(payload, **{victim: (content + b'+', kind)})),
            ('mode', dict(payload, **{victim: (content, kind ^ 0o001)})),
            ('missing member', {k: v for k, v in payload.items() if k != victim}),
            ('extra member', dict(payload, **{'added-later.txt': (b'later', stat.S_IFREG | 0o644)})),
        ):
            with self.assertRaises(ValueError, msg=name):
                package.verify_zip(zipped, changed, 'berman-analysis/')
        with self.assertRaises(ValueError):
            package.verify_zip(zipped, payload, 'stewart-analysis/')


if __name__ == '__main__':
    unittest.main()
